defp fold_events(events, start_seq) do
  Enum.reduce_while(events, {:ok, 0, start_seq}, fn event, {:ok, applied, _last_seq} ->
    case apply_to_projection(event) do
      :ok ->
        {:cont, {:ok, applied + 1, event.sequence}}

      {:error, reason} ->
        {:halt, {:error, {:fold_failed, event.sequence, reason}, event_prev_seq(event, start_seq)}}
    end
  end)
  |> case do
    {:ok, applied, last_seq} -> {:ok, applied, last_seq}
    {:error, error, last_seq} -> {:error, error, last_seq}
  end
end

# Tracks the last *successfully* applied sequence when a fold fails midway.
defp event_prev_seq(_event, start_seq), do: start_seq

